import 'package:dharm_guru_shrinkhala/services/astro.dart';
import 'package:flutter_test/flutter_test.dart';

/// Phase 3 time and location tests. Rise and set references
/// are Skyfield 1.55 with JPL DE421, generated by
/// docs/implementation/generate_reference_cases.py.
void main() {
  const Duration ist = Duration(hours: 5, minutes: 30);

  group('julianDay', () {
    test('J2000.0 is JD 2451545.0', () {
      expect(julianDay(DateTime.utc(2000, 1, 1, 12)), 2451545.0);
    });

    test('canonical birth instant is JD 2450886.54', () {
      expect(
        julianDay(DateTime.utc(1998, 3, 14, 0, 55)),
        closeTo(2450886.5382, 0.001),
      );
    });

    test('leap day 29 February 2000 exists and converts', () {
      expect(julianDay(DateTime.utc(2000, 2, 29, 6, 30)), greaterThan(0));
      expect(
        julianDay(DateTime.utc(2000, 3, 1, 6, 30)) -
            julianDay(DateTime.utc(2000, 2, 29, 6, 30)),
        closeTo(1.0, 0.001),
      );
    });
  });

  group('indiaUtcOffset', () {
    test('IST is plus 5 hours 30 minutes after 1906', () {
      expect(
        indiaUtcOffset(local: DateTime(1998, 3, 14), longitude: 75.7873),
        ist,
      );
      expect(
        indiaUtcOffset(local: DateTime(1906, 1, 1), longitude: 75.7873),
        ist,
      );
    });

    test('wartime daylight saving is plus 6 hours 30 minutes', () {
      expect(
        indiaUtcOffset(local: DateTime(1942, 5, 14), longitude: 75.7873),
        ist,
      );
      expect(
        indiaUtcOffset(local: DateTime(1942, 5, 15), longitude: 75.7873),
        const Duration(hours: 6, minutes: 30),
      );
      expect(
        indiaUtcOffset(local: DateTime(1943, 6, 15), longitude: 75.7873),
        const Duration(hours: 6, minutes: 30),
      );
      expect(
        indiaUtcOffset(local: DateTime(1945, 10, 15), longitude: 75.7873),
        const Duration(hours: 6, minutes: 30),
      );
      expect(
        indiaUtcOffset(local: DateTime(1945, 10, 16), longitude: 75.7873),
        ist,
      );
    });

    test('before 1906 the offset is local mean time', () {
      // Jaipur 75.7873 east times 4 minutes a degree.
      expect(
        indiaUtcOffset(local: DateTime(1900, 6, 15), longitude: 75.7873),
        const Duration(minutes: 303),
      );
      expect(
        indiaUtcOffset(local: DateTime(1905, 12, 31), longitude: 75.7873),
        const Duration(minutes: 303),
      );
      // Noon on the last pre IST day is still local mean time.
      expect(
        indiaUtcOffset(
          local: DateTime(1905, 12, 31, 12),
          longitude: 75.7873,
        ),
        const Duration(minutes: 303),
      );
      // Noon on the last pre DST day is still IST.
      expect(
        indiaUtcOffset(
          local: DateTime(1942, 5, 14, 12),
          longitude: 75.7873,
        ),
        ist,
      );
    });
  });

  group('sunriseSunset', () {
    test('Jaipur 14 March 1998 matches Skyfield within 5 minutes', () {
      final ({DateTime sunrise, DateTime sunset}) times = sunriseSunset(
        day: DateTime(1998, 3, 14),
        place: kDefaultPlace,
        utcOffset: ist,
      );
      // Skyfield: sunrise 01:07:57 UTC, sunset 13:04:47 UTC.
      final DateTime expectedSunrise = DateTime(1998, 3, 14, 6, 37, 57);
      final DateTime expectedSunset = DateTime(1998, 3, 14, 18, 34, 47);
      expect(
        times.sunrise.difference(expectedSunrise).inMinutes.abs(),
        lessThanOrEqualTo(5),
      );
      expect(
        times.sunset.difference(expectedSunset).inMinutes.abs(),
        lessThanOrEqualTo(5),
      );
    });

    test('Delhi 29 February 2000 matches Skyfield within 5 minutes', () {
      final AstroPlace delhi = placeFor('Delhi')!;
      final ({DateTime sunrise, DateTime sunset}) times = sunriseSunset(
        day: DateTime(2000, 2, 29),
        place: delhi,
        utcOffset: ist,
      );
      // Skyfield: sunrise 01:17:16 UTC, sunset 12:50:28 UTC.
      expect(
        times.sunrise
            .difference(DateTime(2000, 2, 29, 6, 47, 16))
            .inMinutes
            .abs(),
        lessThanOrEqualTo(5),
      );
      expect(
        times.sunset
            .difference(DateTime(2000, 2, 29, 18, 20, 28))
            .inMinutes
            .abs(),
        lessThanOrEqualTo(5),
      );
    });

    test('Sydney 15 June 2005 sunrise matches Skyfield', () {
      const AstroPlace sydney = AstroPlace('Sydney', -33.8688, 151.2093);
      final ({DateTime sunrise, DateTime sunset}) times = sunriseSunset(
        day: DateTime(2005, 6, 15),
        place: sydney,
        utcOffset: const Duration(hours: 10),
      );
      // Skyfield: sunrise 20:58:11 UTC 14 June, 06:58 local.
      expect(
        times.sunrise
            .difference(DateTime(2005, 6, 15, 6, 58, 11))
            .inMinutes
            .abs(),
        lessThanOrEqualTo(5),
      );
      // Southern winter: short day, sunrise after 06:30 and
      // sunset before 17:30 local.
      expect(times.sunset.hour, lessThan(18));
      expect(
        times.sunset.difference(times.sunrise),
        lessThan(const Duration(hours: 11)),
      );
    });
  });

  group('moonriseMoonset', () {
    test('Jaipur 14 March 1998 matches Skyfield within 15 minutes', () {
      final ({DateTime? moonrise, DateTime? moonset}) times =
          moonriseMoonset(
        day: DateTime(1998, 3, 14),
        place: kDefaultPlace,
        utcOffset: ist,
      );
      // Skyfield: moonset 01:44:31 UTC, moonrise 14:09:49 UTC.
      expect(times.moonset, isNotNull);
      expect(times.moonrise, isNotNull);
      expect(
        times.moonset!
            .difference(DateTime(1998, 3, 14, 7, 14, 31))
            .inMinutes
            .abs(),
        lessThanOrEqualTo(15),
      );
      expect(
        times.moonrise!
            .difference(DateTime(1998, 3, 14, 19, 39, 49))
            .inMinutes
            .abs(),
        lessThanOrEqualTo(15),
      );
    });

    test('moonrise comes after moonset on a waning day', () {
      final ({DateTime? moonrise, DateTime? moonset}) times =
          moonriseMoonset(
        day: DateTime(2026, 12, 8),
        place: kDefaultPlace,
        utcOffset: ist,
      );
      // Skyfield new moon day: moonrise 00:56 UTC, moonset
      // 11:17 UTC, both on the same local day.
      expect(times.moonrise, isNotNull);
      expect(times.moonset, isNotNull);
      expect(times.moonrise!.isBefore(times.moonset!), isTrue);
    });
  });

  group('localSolarDay', () {
    test('Jaipur solar day runs sunrise to next sunrise', () {
      final ({DateTime sunrise, DateTime nextSunrise, Duration length})
          day = localSolarDay(
        day: DateTime(1998, 3, 14),
        place: kDefaultPlace,
        utcOffset: ist,
      );
      expect(day.sunrise.hour, 6);
      expect(day.nextSunrise.isAfter(day.sunrise), isTrue);
      expect(day.length, greaterThan(const Duration(hours: 23)));
      expect(day.length, lessThan(const Duration(hours: 25)));
    });
  });

  group('ayanamsha modes', () {
    test('Lahiri at J2000 is 23.853 degrees', () {
      // Engine day number for 2000-01-01 12:00 UTC is 1.5.
      expect(ayanamshaFor(AyanamshaMode.lahiri, 1.5), closeTo(23.853, 0.01));
    });

    test('Raman is Lahiri minus 1 degree 26 minutes', () {
      const double d = 1.5;
      expect(
        ayanamshaFor(AyanamshaMode.lahiri, d) -
            ayanamshaFor(AyanamshaMode.raman, d),
        closeTo(1.4333, 0.01),
      );
      expect(ayanamshaFor(AyanamshaMode.raman, d), closeTo(22.42, 0.05));
    });

    test('Krishnamurti is Lahiri minus 6 arcminutes', () {
      const double d = 1.5;
      expect(
        ayanamshaFor(AyanamshaMode.lahiri, d) -
            ayanamshaFor(AyanamshaMode.krishnamurti, d),
        closeTo(0.1, 0.01),
      );
      expect(
        ayanamshaFor(AyanamshaMode.krishnamurti, d),
        closeTo(23.753, 0.02),
      );
    });
  });

  group('node modes', () {
    test('true node at the canonical birth matches Skyfield', () {
      // Canonical instant 1998-03-14 00:55 UTC. Skyfield true
      // node 160.61 tropical by the Moon latitude crossing.
      final double d = julianDay(DateTime.utc(1998, 3, 14, 0, 55)) -
          2451543.5;
      expect(
        nodeLongitude(d, NodeMode.trueNode),
        closeTo(160.61, 0.5),
      );
      expect(
        nodeLongitude(d, NodeMode.mean),
        closeTo(159.91, 0.1),
      );
      // True minus mean is plus 0.70 degrees here.
      expect(
        nodeLongitude(d, NodeMode.trueNode) -
            nodeLongitude(d, NodeMode.mean),
        closeTo(0.70, 0.5),
      );
    });

    test('Ketu is always 180 degrees from Rahu', () {
      final double d = julianDay(DateTime.utc(2025, 12, 1, 12)) -
          2451543.5;
      final double rahu = nodeLongitude(d, NodeMode.trueNode);
      // True node about 343.97 tropical, so Ketu is about
      // 163.97, exactly 180 degrees opposite.
      expect(rahu, closeTo(343.97, 0.5));
      expect((rahu + 180.0) % 360.0, closeTo(163.97, 0.5));
    });
  });
}
